#include <stdio.h>

// Function to calculate the carbon footprint
// Parameters:
//   electricity_consumed: electricity consumed in kWh (double)
//   emission_factor: emission factor in kgCO2e/kWh (double)
// Returns:
//   Carbon footprint (double)
double calculate_carbon_footprint(double electricity_consumed, double emission_factor) {
    return electricity_consumed * emission_factor;
}

int main() {
    double electricity_consumed = 100.0; // Example value in kWh
    double emission_factor = 0.5; // Example value in kgCO2e/kWh
    double carbon_footprint = calculate_carbon_footprint(electricity_consumed, emission_factor);
    printf("Carbon Footprint: %.2f kgCO2e\n", carbon_footprint);
    return 0;
}"}]

